package com.ryanjei.orushio.pve.paper;
import static org.junit.jupiter.api.Assertions.*;import java.util.List;import org.junit.jupiter.api.Test;
class MapSetupMessagesTest{@Test void 単一点は日本語項目名で完了を伝える(){assertEquals(List.of("[OPBP] ファーム開始地点を設定しました。"),MapSetupMessages.completed("farmSpawn",false,true));assertEquals(List.of("[OPBP] スポーン地点を設定しました。"),MapSetupMessages.completed("spawnMarker",false,true));}@Test void 範囲は一点目二点目と完了を伝える(){assertEquals(List.of("[OPBP] ファーム範囲の1地点目を設定しました。","[OPBP] 2地点目を指定してください。"),MapSetupMessages.completed("farmRegion",true,false));assertEquals(List.of("[OPBP] ファーム範囲の2地点目を設定しました。","[OPBP] ファーム範囲の登録が完了しました。"),MapSetupMessages.completed("farmRegion",true,true));}@Test void 座標をMinecraft向け文言で表示する(){var p=new com.ryanjei.orushio.pve.map.BlockPoint(100,64,-20,0,0);assertEquals(List.of("[OPBP] 資源ゾーンの1地点目を設定しました。 X=100 Y=64 Z=-20","[OPBP] 2地点目を指定してください。"),MapSetupMessages.completed("resourceZones",true,false,p));}}
